BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L3 — Clearly trivial threshold and accumulation
(1, 'Misstatements and Control Deficiencies', 'During the audit of Meridian Electronics, the auditor identifies a $200 error in office supplies expense. Overall materiality for the engagement is $500,000. The auditor determines this amount is clearly trivial. Under AU-C 450, the auditor should:', '["Need not accumulate the misstatement on the summary of uncorrected misstatements", "Accumulate and report the misstatement to those charged with governance", "Accumulate the misstatement and request management correction before year-end", "Document the misstatement but exclude it from the aggregate evaluation"]'::jsonb, 0, 'Under AU-C 450.05, the auditor accumulates all identified misstatements during the audit other than those that are clearly trivial. A $200 error against $500,000 materiality (0.04%) falls below any reasonable threshold and need not be accumulated. Choice B is incorrect because clearly trivial items are specifically excluded from the accumulation and communication requirements under AU-C 450.', 'medium', 3),

-- Q2: medium / L3 — Iron curtain vs rollover evaluation
(1, 'Misstatements and Control Deficiencies', 'While evaluating uncorrected misstatements at Crestline Manufacturing, the auditor notes a $40,000 revenue overstatement originating in the prior year that reverses in the current year. The current-year income statement shows a $40,000 understatement. Under AU-C 450, the auditor should evaluate this misstatement by considering:', '["Only the current-year income statement effect of the $40,000 understatement", "Both the current-year income statement effect and the cumulative balance sheet effect", "Only the cumulative balance sheet effect since the income statement impact reverses", "Neither effect since the misstatement originated in a prior period"]'::jsonb, 1, 'Under AU-C 450.A16, the auditor considers both the income statement (rollover) and balance sheet (iron curtain) effects when evaluating uncorrected misstatements. A prior-year revenue overstatement that reverses creates a current-year understatement while the cumulative balance sheet effect may persist. Choice A is incorrect because ignoring the balance sheet impact could overlook a material misstatement in retained earnings or related accounts.', 'medium', 3),

-- Q3: medium / L3 — Omitted disclosures as misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Granite Peak Hospitality, the auditor discovers that a required related-party disclosure was omitted from the financial statements. No dollar amounts are misstated in the statements themselves. Under AU-C 450, the auditor should treat this omission as:', '["An immaterial omission since no dollar amounts are affected", "A disclosure deficiency requiring a separate communication to regulators", "A misstatement that should be accumulated and evaluated for materiality", "A scope limitation requiring qualification of the audit opinion"]'::jsonb, 2, 'Under AU-C 450.04, misstatements include both quantitative and qualitative misstatements in the financial statements, including inadequate or omitted disclosures. The auditor must accumulate this disclosure omission and evaluate whether it is material individually or in the aggregate. Choice A is incorrect because qualitative misstatements such as omitted disclosures can be material regardless of whether any reported dollar amounts are misstated.', 'medium', 3),

-- Q4: medium / L3 — Dual-purpose test revealing control deficiency
(1, 'Misstatements and Control Deficiencies', 'At Sycamore Industries, the auditor performs a dual-purpose test on purchase order approvals, testing both control effectiveness and amount accuracy. The test reveals that 8 of 40 purchase orders lacked required supervisory approval, though all amounts were correctly recorded. The auditor should:', '["Evaluate the approval failures as a control deficiency and assess its severity under AU-C 265", "Disregard the missing approvals since all recorded amounts were accurate", "Report the finding only as a substantive testing exception in the audit file", "Communicate the missing approvals exclusively as a fraud risk indicator"]'::jsonb, 0, 'Under AU-C 265.07, a control deficiency exists when a control is designed, implemented, or operated such that it cannot prevent or detect misstatements on a timely basis. An 8-of-40 (20%) failure rate in supervisory approvals represents a control operating deficiency requiring severity evaluation. Choice B is incorrect because control deficiencies are evaluated based on their potential to allow misstatements, not whether misstatements actually occurred in the sample tested.', 'medium', 3),

-- Q5: easy / L1 — Tolerable misstatement definition
(1, 'Misstatements and Control Deficiencies', 'What is tolerable misstatement in the context of audit sampling?', '["The maximum misstatement that can exist before the auditor modifies the opinion", "The total amount of all detected errors in an audit sample", "The threshold below which misstatements are considered clearly trivial", "The maximum misstatement in a population the auditor is willing to accept"]'::jsonb, 3, 'Under AU-C 530.A3, tolerable misstatement is the application of performance materiality to a particular sampling procedure. It represents the maximum amount of misstatement the auditor is willing to accept in the population and still conclude the sampling objective is met. Choice A is incorrect because it describes overall materiality, not tolerable misstatement, which is set lower than materiality for individual account testing.', 'easy', 1),

-- Q6: easy / L1 — Deficiency in design definition
(1, 'Misstatements and Control Deficiencies', 'What is a deficiency in the design of an internal control?', '["A control that exists but fails to operate as intended by personnel", "A control that functions properly but is not documented in policy manuals", "A control that was previously effective but has deteriorated over time", "A control that is missing or not properly designed to meet the control objective"]'::jsonb, 3, 'Under AU-C 265.07, a deficiency in design exists when a necessary control is missing or when an existing control is not properly designed to prevent or detect misstatements on a timely basis, even if it operates as designed. Choice A is incorrect because it describes a deficiency in operation, where the control is properly designed but personnel fail to execute it effectively.', 'easy', 1),

-- Q7: hard / L4 — Qualitative and quantitative evaluation combined
(1, 'Misstatements and Control Deficiencies', 'During the audit of Pacific Rim Importers, the auditor identifies uncorrected misstatements totaling $180,000 against overall materiality of $250,000. Of this total, $95,000 relates to revenue recognition timing, $50,000 to an intentional reclassification of operating expenses as capital items, and $35,000 to routine immaterial differences. When forming the audit opinion, the auditor should evaluate these misstatements by:', '["Comparing only the $180,000 aggregate to the $250,000 materiality threshold and concluding the statements are not materially misstated", "Considering both the $180,000 quantitative proximity to materiality and the qualitative nature of the intentional reclassification", "Removing the $35,000 routine differences from the evaluation since they are immaterial individually", "Requesting management correct only the $95,000 revenue recognition error since it is the largest item"]'::jsonb, 1, 'Under AU-C 450.11, the auditor evaluates whether uncorrected misstatements are material individually or in the aggregate, considering both size and nature. While $180,000 is below the $250,000 threshold, the intentional expense reclassification raises qualitative concerns about management bias under AU-C 450.A22. Choice A is incorrect because a purely quantitative comparison ignores qualitative factors such as the intentional nature of misstatements, which could indicate management bias.', 'hard', 4),

-- Q8: easy / L2 — Communication timing for significant deficiencies
(1, 'Misstatements and Control Deficiencies', 'At Birchwood Community Hospital, the auditor identifies a significant deficiency in payroll processing controls during interim fieldwork in September. The fiscal year-end is December 31 and the audit report will be issued in March. Under AU-C 265, the auditor should communicate the significant deficiency:', '["In writing no later than 60 days following the report release date", "Verbally during the September interim fieldwork with no written follow-up required", "Only after completing all year-end audit procedures to confirm the deficiency persists", "Within 30 days of identifying the deficiency during interim fieldwork"]'::jsonb, 0, 'Under AU-C 265.13, the auditor must communicate significant deficiencies and material weaknesses in writing to those charged with governance no later than 60 days following the report release date. There is no requirement for immediate communication during interim work, though timely communication is encouraged. Choice B is incorrect because AU-C 265 specifically requires written communication; verbal-only notification does not satisfy the standard.', 'easy', 2),

-- Q9: hard / L4 — Group audit misstatement aggregation
(1, 'Misstatements and Control Deficiencies', 'The group engagement team for Pinnacle Holdings evaluates component misstatements reported by three component auditors. Component A reports $120,000 in uncorrected misstatements, Component B reports $75,000, and Component C reports $90,000. Group materiality is $800,000 and component materiality levels were set at $200,000 each. The group engagement partner should:', '["Accept each component''s misstatements as immaterial since none exceed the $200,000 component materiality", "Evaluate only Component A''s misstatements since they represent the largest single amount reported", "Aggregate all component misstatements totaling $285,000 and evaluate against the $800,000 group materiality", "Request each component auditor to independently evaluate their misstatements against group materiality"]'::jsonb, 2, 'Under AU-C 600.50, the group engagement team must evaluate the aggregate effect of uncorrected misstatements from all components against group materiality. While each component''s misstatements fall below component materiality, the combined $285,000 must be assessed at the group level. Choice A is incorrect because evaluating component misstatements only at the component level ignores their aggregate effect on the consolidated financial statements.', 'hard', 4),

-- Q10: hard / L4 — Management override as control deficiency indicator
(1, 'Misstatements and Control Deficiencies', 'During the audit of Ridgeline Energy Corporation, the auditor discovers that the CEO personally approved three vendor payments totaling $2.1 million that bypassed the standard three-level authorization process. The CEO claims the transactions were time-sensitive. The company processes $400 million in vendor payments annually. The auditor should:', '["Accept the CEO''s explanation since the override did not result in any identified monetary misstatement", "Classify the override as a significant deficiency since the amounts are small relative to total payments", "Report the finding as a control deficiency but reduce its severity because the CEO acted in good faith", "Evaluate whether the management override indicates a material weakness regardless of the stated justification"]'::jsonb, 3, 'Under AU-C 265.A13, management override of controls is a specific indicator the auditor should consider when evaluating deficiency severity. The ability of senior management to bypass established authorization processes affects the entire control environment regardless of stated business purpose. Choice B is incorrect because the severity assessment should focus on the nature and implications of management override for the control environment, not merely the dollar magnitude relative to total transactions.', 'hard', 4),

-- Q11: medium / L2 — Prior-period uncorrected misstatements carryforward
(1, 'Misstatements and Control Deficiencies', 'During the current-year audit of Lakewood Distributors, the auditor reviews the prior-year summary of uncorrected misstatements, which included a $60,000 inventory overstatement that management did not correct. Under AU-C 450, the auditor''s current-year evaluation should:', '["Exclude the prior-year misstatement since it was already evaluated and accepted", "Include only the current-year reversal effect of the prior-year misstatement", "Consider the prior-year uncorrected misstatement''s effect on the current-year financial statements", "Require management to correct the prior-year misstatement before issuing the current report"]'::jsonb, 2, 'Under AU-C 450.11, the auditor evaluates whether uncorrected misstatements are material, individually or in the aggregate, including the effect of uncorrected misstatements related to prior periods on the current-year financial statements. A prior-year inventory overstatement affects current cost of goods sold. Choice A is incorrect because prior-year uncorrected misstatements do not disappear; their carryforward effects must be considered in the current-year aggregate evaluation.', 'medium', 2),

-- Q12: hard / L3 — Subsequent event confirming year-end misstatement
(1, 'Misstatements and Control Deficiencies', 'After completing fieldwork for Coastal Marine Industries but before issuing the audit report, the auditor learns that a major customer filed for bankruptcy, revealing that a $350,000 receivable was uncollectible at year-end. The allowance for doubtful accounts included no reserve for this customer. Overall materiality is $400,000. The auditor should:', '["Disclose the bankruptcy as a subsequent event without adjusting the recorded amounts", "Treat this as a Type II subsequent event requiring footnote disclosure only", "Communicate the finding as a significant deficiency in the credit approval process", "Request management adjust the financial statements to record the $350,000 loss since the condition existed at year-end"]'::jsonb, 3, 'Under AU-C 560.09, when a subsequent event provides evidence of conditions that existed at the balance sheet date, the financial statements should be adjusted. The customer''s bankruptcy confirms the receivable was impaired at year-end, making this a Type I subsequent event requiring adjustment. Choice A is incorrect because Type I subsequent events that confirm year-end conditions require financial statement adjustment, not merely disclosure as appropriate for Type II events.', 'hard', 3),

-- Q13: easy / L1 — Purpose of summary of uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'What is the purpose of the summary of uncorrected misstatements maintained by the auditor?', '["To accumulate identified misstatements so the auditor can evaluate their aggregate effect on the financial statements", "To provide management with a list of adjustments that must be recorded before the report is issued", "To document the basis for a qualified audit opinion when misstatements exist", "To calculate the final materiality level for the audit engagement"]'::jsonb, 0, 'Under AU-C 450.05, the auditor accumulates all identified misstatements during the audit, other than those that are clearly trivial, to evaluate their aggregate effect on the financial statements. This summary supports the auditor''s conclusion about whether the statements are materially misstated. Choice B is incorrect because the summary includes misstatements management chose not to correct; it is an auditor evaluation tool, not a mandatory adjustment list for management.', 'easy', 1),

-- Q14: easy / L1 — Deficiency in operation definition
(1, 'Misstatements and Control Deficiencies', 'What is a deficiency in the operation of an internal control?', '["A control that was never designed to address the relevant financial statement assertion", "A control that is properly designed but not performed effectively by responsible individuals", "A control that has been formally documented but never implemented in practice", "A control that addresses only one assertion when multiple assertions require coverage"]'::jsonb, 1, 'Under AU-C 265.07, a deficiency in operation exists when a properly designed control does not operate effectively—meaning the person performing the control does not possess the authority or competence, or does not perform the control correctly. Choice A is incorrect because a missing or improperly designed control describes a design deficiency, not an operating deficiency, which relates to execution failures of otherwise adequate controls.', 'easy', 1),

-- Q15: medium / L2 — Documentation requirements for misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Cedar Ridge Properties, the engagement team identifies 14 misstatements ranging from $500 to $45,000. Overall materiality is $300,000. The engagement partner asks what documentation AU-C 450 requires. The appropriate response is that the auditor must document:', '["Only misstatements exceeding 5% of overall materiality", "Only misstatements that management refuses to correct", "All accumulated misstatements and whether they were corrected by management", "Only misstatements that individually exceed the clearly trivial threshold and remain uncorrected"]'::jsonb, 2, 'Under AU-C 450.14, the auditor must document the amount below which misstatements are regarded as clearly trivial, all misstatements accumulated during the audit, whether they have been corrected, and the conclusion on whether uncorrected misstatements are material. Choice B is incorrect because the documentation requirement covers all accumulated misstatements regardless of whether management corrected them, not just those remaining uncorrected.', 'medium', 2),

-- Q16: medium / L2 — Known vs projected misstatements from sampling
(1, 'Misstatements and Control Deficiencies', 'While auditing Fieldstone Construction, the auditor tests a sample of 30 contract billings from a population of 600 and finds three errors totaling $12,000. The auditor projects the error to the population and estimates a likely misstatement of $240,000. Under AU-C 450, the auditor should accumulate:', '["Only the $12,000 known misstatement identified in the sample", "Only the $228,000 difference between the projected and known amounts", "The $240,000 projected misstatement minus a reasonable margin for sampling risk", "The full $240,000 projected misstatement as the best estimate of population error"]'::jsonb, 3, 'Under AU-C 450.05 and AU-C 530.A21, when misstatements are found in a sample, the auditor projects the misstatement to the population. The full projected amount of $240,000 is accumulated on the summary of uncorrected misstatements as the best estimate of total population error. Choice A is incorrect because accumulating only known sample errors would understate the likely total misstatement in the population and fail to properly evaluate aggregate materiality.', 'medium', 2),

-- Q17: medium / L3 — Remediation before year-end still requires communication
(1, 'Misstatements and Control Deficiencies', 'During the audit of Heritage Financial Group, the auditor identified a material weakness in loan approval controls in October. Management implemented new controls in November, and the auditor tested the remediated controls in January, finding them effective. The fiscal year-end is December 31. The auditor should:', '["Remove the material weakness from the written communication since it was remediated before year-end", "Still communicate the material weakness because it existed during a portion of the period under audit", "Downgrade the finding to a significant deficiency since remediation occurred before year-end", "Communicate only the successful remediation without referencing the original weakness"]'::jsonb, 1, 'Under AU-C 265.11, the auditor communicates significant deficiencies and material weaknesses identified during the audit regardless of whether management has remediated them by period-end. A material weakness that existed during any portion of the audit period must be reported. Choice A is incorrect because remediation does not eliminate the communication requirement; the weakness existed during part of the period, and governance needs to be informed of conditions that affected the financial statements.', 'medium', 3),

-- Q18: medium / L3 — Control deficiency in monitoring component
(1, 'Misstatements and Control Deficiencies', 'At Brookfield Manufacturing, the internal audit department is responsible for quarterly reviews of journal entry controls. The external auditor discovers that no quarterly reviews were performed during the current year because two internal audit staff resigned and were not replaced for eight months. The auditor should evaluate this finding as:', '["A control deficiency in the monitoring component of internal control that requires severity assessment", "A staffing issue outside the scope of the financial statement audit", "An inherent limitation of internal control that does not constitute a reportable deficiency", "A management representation matter to be addressed in the engagement letter"]'::jsonb, 0, 'Under AU-C 265.A1 and the COSO framework, monitoring activities are a component of internal control. The failure to perform quarterly journal entry reviews due to staffing gaps represents a deficiency in the monitoring component that must be evaluated for severity. Choice B is incorrect because staffing failures that prevent execution of monitoring controls directly affect the entity''s ability to prevent or detect financial statement misstatements and fall within the audit scope.', 'medium', 3),

-- Q19: medium / L2 — Fraud versus error distinction
(1, 'Misstatements and Control Deficiencies', 'During the audit of Stonebridge Retail, the auditor finds that a store manager intentionally recorded fictitious sales returns totaling $28,000 to embezzle cash refunds. Separately, the auditor finds a $15,000 computational error in depreciation. Under auditing standards, the key distinction between these two misstatements is:', '["The dollar amount determines whether the misstatement is classified as fraud or error", "Fraud misstatements affect the balance sheet while error misstatements affect only the income statement", "Fraud misstatements require reporting to law enforcement while error misstatements require only management notice", "Fraud misstatements result from intentional acts while error misstatements result from unintentional mistakes"]'::jsonb, 3, 'Under AU-C 240.02, the distinguishing factor between fraud and error is intent. Fraud involves intentional misstatements, including misappropriation of assets, while errors are unintentional misstatements such as computational mistakes. Both are accumulated under AU-C 450. Choice C is incorrect because auditing standards do not require the auditor to report fraud directly to law enforcement; the primary communication obligation is to management and those charged with governance under AU-C 240.39-.40.', 'medium', 2),

-- Q20: medium / L2 — Magnitude and likelihood in severity evaluation
(1, 'Misstatements and Control Deficiencies', 'At Clearwater Technology, the auditor identifies that accounts payable clerks do not match receiving reports to vendor invoices before processing payments. The control processes approximately $8 million in disbursements annually and no compensating controls exist. Under AU-C 265, the auditor evaluates severity by assessing:', '["The total dollar amount of payments processed through the deficient control during the year", "The number of transactions affected by the deficiency relative to total transaction volume", "The magnitude of potential misstatement and the likelihood that misstatements could result from the deficiency", "Whether any actual misstatements were detected in the accounts payable balance at year-end"]'::jsonb, 2, 'Under AU-C 265.A8, the severity of a control deficiency depends on the magnitude of the potential misstatement and the likelihood that the deficiency could result in a misstatement. Both factors must be considered together to determine whether the deficiency is a significant deficiency or material weakness. Choice D is incorrect because severity is based on potential for misstatement, not solely on whether actual misstatements were identified; a deficiency can be severe even without detected errors.', 'medium', 2),

-- Q21: hard / L4 — Pervasive misstatements and adverse opinion
(1, 'Misstatements and Control Deficiencies', 'The auditor of Sunland Enterprises identifies uncorrected misstatements in revenue ($95,000 overstatement), inventory ($110,000 overstatement), and accounts payable ($85,000 understatement), all caused by the same flawed ERP configuration. Overall materiality is $200,000 and the aggregate is $290,000. Management refuses to correct. When determining the appropriate opinion, the auditor should consider that:', '["The misstatements are both material and pervasive because they affect multiple elements due to a common cause, supporting an adverse opinion", "Each individual misstatement is below materiality so a qualified opinion is appropriate regardless of the common cause", "The common cause is an IT issue outside the financial statement audit scope, warranting a disclaimer of opinion", "The auditor should withdraw from the engagement since management refuses to correct material misstatements"]'::jsonb, 0, 'Under AU-C 705.09-.10, when misstatements are both material and pervasive—affecting multiple elements, accounts, or disclosures representing a substantial proportion of the financial statements—an adverse opinion is appropriate. The common ERP cause creates systemic risk across multiple accounts. Choice B is incorrect because individual immateriality is irrelevant when the aggregate exceeds materiality and the pervasive common root cause affects overall financial statement presentation.', 'hard', 4),

-- Q22: medium / L2 — Communication of lesser deficiencies to management
(1, 'Misstatements and Control Deficiencies', 'During the audit of Harborview Medical Center, the auditor identifies control deficiencies in supply chain receiving that do not rise to the level of significant deficiencies or material weaknesses. Under AU-C 265, the auditor''s obligation regarding these lesser deficiencies is to:', '["Include them in the written communication alongside significant deficiencies sent to governance", "Determine whether to communicate them to management based on professional judgment", "Document them in the audit file but withhold communication to avoid overburdening management", "Communicate them only if management specifically requests a comprehensive listing of findings"]'::jsonb, 1, 'Under AU-C 265.12, the auditor should consider whether to communicate control deficiencies that are not significant deficiencies or material weaknesses to management. This is a matter of professional judgment based on the circumstances. Choice A is incorrect because AU-C 265 only requires written communication to governance for significant deficiencies and material weaknesses; lesser deficiencies may be communicated to management at the auditor''s discretion.', 'medium', 2),

-- Q23: hard / L4 — Accounting estimate difference as likely misstatement
(1, 'Misstatements and Control Deficiencies', 'While auditing Cascade Insurance, the auditor develops an independent estimate of the loss reserve at $14.2 million. Management''s recorded reserve is $12.8 million. The actuarial range is $12.5 million to $15.0 million. Overall materiality is $2.0 million. The $1.4 million difference is below materiality. The auditor should:', '["Accept management''s estimate since it falls within the actuarial range and the difference is below materiality", "Require management to adjust to the midpoint of the actuarial range as the best estimate", "Accumulate the $1.4 million as a likely misstatement and evaluate it in the aggregate with other uncorrected items", "Disclose the actuarial range in the audit report since the estimate involves significant uncertainty"]'::jsonb, 2, 'Under AU-C 540.A126 and AU-C 450, when management''s estimate differs from the auditor''s point estimate, the difference is treated as a likely misstatement and accumulated. Even though $1.4 million is below $2.0 million materiality and within the range, it must be included in the aggregate evaluation. Choice A is incorrect because falling within a reasonable range does not exempt the difference from accumulation; combined with other uncorrected misstatements, it could contribute to a material aggregate.', 'hard', 4),

-- Q24: medium / L3 — Aggregate evaluation with undetected misstatement risk
(1, 'Misstatements and Control Deficiencies', 'The audit team at Northwind Technologies accumulated misstatements of $18,000 in receivables, $12,000 in payables, $25,000 in prepaid expenses, $8,000 in accrued liabilities, and $7,000 in inventory. Overall materiality is $150,000. Before forming a conclusion, the engagement partner should:', '["Dismiss all misstatements since each individually is well below materiality", "Focus only on the prepaid expenses misstatement as the largest single item", "Request management correct only misstatements exceeding 10% of materiality", "Evaluate the $70,000 aggregate and consider whether additional misstatements may exist in untested areas"]'::jsonb, 3, 'Under AU-C 450.11, the auditor evaluates whether uncorrected misstatements are material individually or in the aggregate. The $70,000 aggregate (47% of materiality) warrants consideration of whether further undetected misstatements exist in untested portions of the financial statements. Choice A is incorrect because even when individual misstatements are immaterial, their aggregate effect must be evaluated and the auditor must consider the risk that total uncorrected and undetected misstatements exceed materiality.', 'medium', 3),

-- Q25: medium / L2 — IT segregation of duties as control deficiency
(1, 'Misstatements and Control Deficiencies', 'During the audit of Terravista Networks, the auditor discovers that accounts payable clerks can both create new vendor records and approve payments in the ERP system without a segregation of duties control. No compensating controls exist. Under AU-C 265, this IT access control gap is best classified as:', '["A control deficiency whose severity depends on the likelihood and magnitude of potential misstatement from inadequate segregation", "An IT governance issue that falls outside the financial statement auditor''s responsibility", "A fraud risk factor that must be reported directly to law enforcement authorities", "An inherent limitation of IT systems that the auditor should document but not report"]'::jsonb, 0, 'Under AU-C 265.07-.08, inadequate segregation of duties in IT systems constitutes a control deficiency that the auditor must evaluate for severity. The ability to create vendors and approve payments without oversight creates potential for unauthorized disbursements. Choice B is incorrect because IT access controls affecting financial transaction processing are directly within the scope of a financial statement audit, and segregation of duties gaps must be evaluated under AU-C 265.', 'medium', 2),

-- Q26: easy / L1 — Three types of misstatements
(1, 'Misstatements and Control Deficiencies', 'What are the three types of misstatements identified in auditing standards?', '["Known, possible, and estimated misstatements", "Factual, judgmental, and projected misstatements", "Material, immaterial, and trivial misstatements", "Intentional, unintentional, and systematic misstatements"]'::jsonb, 1, 'Under AU-C 450.A2-.A4, misstatements are classified as factual (no doubt about their existence), judgmental (arising from management''s unreasonable judgments about estimates or accounting policies), and projected (the auditor''s best estimate of population misstatements based on sampling). Choice A is incorrect because "known, possible, and estimated" are not the standard classifications; the authoritative terminology uses factual, judgmental, and projected.', 'easy', 1),

-- Q27: easy / L1 — Strong indicator of material weakness
(1, 'Misstatements and Control Deficiencies', 'Under auditing standards, which of the following is a strong indicator of a material weakness?', '["A single immaterial error discovered during substantive testing procedures", "Management''s failure to implement a recommendation from the prior-year management letter", "Identification of fraud committed by senior management regardless of dollar amount", "A turnover rate exceeding 20% in the accounting department during the year"]'::jsonb, 2, 'Under AU-C 265.A14, identification of fraud committed by senior management, even if immaterial in amount, is a strong indicator of a material weakness because it signals a breakdown in the control environment. The integrity and ethical values of senior management underpin the entire control system. Choice D is incorrect because while high turnover may create control risks, it is not by itself a strong indicator of material weakness without evidence that controls actually failed.', 'easy', 1),

-- Q28: easy / L1 — Written communication format requirement
(1, 'Misstatements and Control Deficiencies', 'In what format must the auditor communicate significant deficiencies to those charged with governance?', '["Verbally during the closing meeting with a summary documented in the minutes", "Through a formal presentation to the full board of directors at the next meeting", "Either written or verbal format at the auditor''s discretion based on severity", "In writing, no later than 60 days following the audit report release date"]'::jsonb, 3, 'Under AU-C 265.13, the auditor must communicate significant deficiencies and material weaknesses to those charged with governance in writing no later than 60 days following the report release date. Verbal communication alone is insufficient to meet the standard. Choice C is incorrect because AU-C 265 specifically requires written communication for significant deficiencies and material weaknesses; there is no option for verbal-only communication regardless of circumstances.', 'easy', 1),

-- Q29: easy / L1 — Clearly trivial meaning
(1, 'Misstatements and Control Deficiencies', 'What does "clearly trivial" mean when evaluating audit misstatements?', '["A misstatement that is inconsequential individually and in the aggregate, whether judged by size, nature, or circumstances", "Any misstatement below 1% of overall materiality for the engagement", "A misstatement that management has agreed to correct before financial statements are issued", "A misstatement found in a non-material account balance or disclosure"]'::jsonb, 0, 'Under AU-C 450.A2, clearly trivial is not another expression for "not material." Matters that are clearly trivial are inconsequential whether taken individually or in the aggregate, judged by any criteria of size, nature, or circumstances. The auditor need not accumulate clearly trivial amounts. Choice B is incorrect because AU-C 450 does not specify a fixed percentage threshold for clearly trivial; the determination involves professional judgment considering all relevant criteria.', 'easy', 1),

-- Q30: medium / L2 — Management representation about uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Pinnacle Aerospace, the auditor communicated a summary of uncorrected misstatements totaling $85,000 to management. Overall materiality is $500,000. Before issuing the audit report, the auditor should obtain from management:', '["A verbal acknowledgment during the closing conference that the uncorrected misstatements exist", "A written representation that management believes the uncorrected misstatements are immaterial to the financial statements", "A signed agreement to correct all uncorrected misstatements within 90 days of the report date", "A formal waiver releasing the auditor from responsibility for the uncorrected misstatements"]'::jsonb, 1, 'Under AU-C 450.12 and AU-C 580.11, the auditor must obtain a written representation from management that it believes the effects of uncorrected misstatements are immaterial, individually and in the aggregate, to the financial statements as a whole. A summary of the items is typically attached. Choice A is incorrect because verbal acknowledgment does not satisfy the requirement; a written representation specifically addressing immateriality of uncorrected items is required.', 'medium', 2)
;

COMMIT;
